void Patch(string name,Type t){try{h!.CreateClassProcessor(t).Patch();Logger.LogInfo("[Luck] "+name+": 적용");}catch(Exception e){Logger.LogWarning("[Luck] "+name+": 비활성 ("+e.GetType().Name+") "+e.Message);}}
void OnDestroy(){h?.UnpatchSelf();}
internal static int Luck(){int l=EClass.pc==null?1:EClass.pc.Evalue(78);return Math.Max(1,Math.Min(9999,l));}
internal static int Rel(ConfigEntry<int>d,ConfigEntry<int>c)=>Math.Min(Math.Max(0,c.Value),Math.Max(0,Luck()/Math.Max(1,d.Value)));
internal static int Reduce(int d,int b){if(d<=1||b<=0)return d;return Math.Max(1,(int)(((long)d*100L+99+b)/(100+b)));}
internal static double Score(int s){int sw=Math.Max(0,SkillW.Value),lw=Math.Max(0,LuckW.Value),den=sw+lw;if(den<=0)return 0;return (Math.Max(0,s)*sw+Luck()*lw)/(double)den;}
internal static double Curve(double x){if(x<=0)return 0;if(x<10)return x/10*.15;if(x<40)return .15+(x-10)/30*.35;if(x<100)return .5+(x-40)/60*.25;if(x<200)return .75+(x-100)/100*.25;return 1+(x-200)/100;}
internal static int Rolls(int s,bool craft=false){double p=Curve(Score(s));if(craft)p/=10;int n=(int)Math.Floor(p);double f=p-n;if(f>0&&EClass.rnd(100000)<(int)(f*100000))n++;return n;}
}
[HarmonyPatch(typeof(Point),nameof(Point.TryWitnessCrime),new Type[]{typeof(Chara),typeof(Chara),typeof(int),typeof(Func<Chara,bool>)})]static class WitnessPatch{static void Prefix(Chara criminal,ref Func<Chara,bool> funcWitness){if(!Plugin.Witness.Value||criminal==null||EClass.pc==null||criminal!=EClass.pc)return;int a=Math.Min(Plugin.WitnessCap.Value,Plugin.Luck()/Math.Max(1,Plugin.WitnessDiv.Value));if(a<=0)return;var old=funcWitness;if(old==null)funcWitness=c=>EClass.rnd(10)==0&&EClass.rnd(100)>=a;else funcWitness=c=>old(c)&&EClass.rnd(100)>=a;}}
[HarmonyPatch(typeof(Trait),nameof(Trait.TryOpenLock),new Type[]{typeof(Chara),typeof(bool)})]static class LockPatch{public sealed class S{public int lv;public bool changed;}static void Prefix(Trait __instance,Chara cc,out S __state){__state=new S();if(!Plugin.Lock.Value||cc==null||!cc.IsPC||__instance.owner==null)return;int cut=Math.Min(Plugin.LockCap.Value,Plugin.Luck()/Math.Max(1,Plugin.LockDiv.Value));__state.lv=__instance.owner.c_lockLv;int n=Math.Max(0,__state.lv-cut);if(n<__state.lv){__instance.owner.c_lockLv=n;__state.changed=true;}}static Exception? Finalizer(Trait __instance,S __state,Exception? e){if(__state!=null&&__state.changed&&__instance.owner.c_lockLv>0)__instance.owner.c_lockLv=__state.lv;return e;}}
[HarmonyPatch(typeof(AI_Fish),nameof(AI_Fish.Makefish),new Type[]{typeof(Chara)})]static class FishPatch{static void Postfix(Chara c,ref Thing __result){if(!Plugin.Fish.Value||c==null||!c.IsPC||__result==null||__result.category==null||!__result.category.IsChildOf("fish"))return;int a=Math.Min(Plugin.FishCap.Value,Plugin.Luck()/Math.Max(1,Plugin.FishDiv.Value));if(__result.tier<3&&EClass.rnd(100)<a)__result.SetTier(Math.Min(3,__result.tier+1));}}
[HarmonyPatch(typeof(Map),nameof(Map.TrySmoothPick),new Type[]{typeof(Point),typeof(Thing),typeof(Chara)})]static class ActivityPatch{static void Prefix(Thing t,Chara c){if(!Plugin.Activity.Value||t==null||c==null||!c.IsPC)return;var fs=new StackTrace(1,false).GetFrames();if(fs==null)return;int skill=-1;bool on=false;for(int i=0;i<fs.Length&&i<12;i++){string n=fs[i].GetMethod()?.DeclaringType?.FullName??"";if(n.Contains("TaskMine")){skill=c.Evalue(220);on=Plugin.Mine.Value;break;}if(n.Contains("TaskDig")){skill=c.Evalue(230);on=Plugin.Dig.Value;break;}if(n.Contains("TaskChopWood")){skill=c.Evalue(225);on=Plugin.Harvest.Value;break;}if(n.Contains("TaskHarvest")||n.Contains("GrowSystem")){skill=Math.Max(c.Evalue(250),c.Evalue(286));on=Plugin.Harvest.Value;break;}}if(!on||skill<0)return;int r=Plugin.Rolls(skill);if(r>0){int b=Math.Max(1,t.Num);t.ModNum(b*r);}}}
[HarmonyPatch(typeof(AI_Fish),nameof(AI_Fish.Makefish),new Type[]{typeof(Chara)})]static class FishBonusPatch{static void Postfix(Chara c,ref Thing __result){if(!Plugin.Activity.Value||!Plugin.FishBonus.Value||c==null||!c.IsPC||__result==null)return;int r=Plugin.Rolls(c.Evalue(245));if(r>0){int b=Math.Max(1,__result.Num);__result.ModNum(b*r);}}}
static class CraftCore{internal static List<Thing>? Prep(Recipe r,List<Thing> ings,bool model){if(!Plugin.Activity.Value||!Plugin.Craft.Value||model||r==null||ings==null||EClass.pc==null)return null;Element e=r.source?.GetReqSkill();int rr=Plugin.Rolls(e==null?0:EClass.pc.Evalue(e.id),true);if(rr<=0)return null;var z=new List<Thing>();foreach(var x in ings)if(x!=null)z.Add(x.Duplicate(Math.Max(1,x.Num)*rr));return z;}internal static void Give(List<Thing>?xs){if(xs==null)return;foreach(var x in xs)EClass.pc.AddCard(x);}}
[HarmonyPatch(typeof(Recipe),nameof(Recipe.Craft),new Type[]{typeof(BlessedState),typeof(bool),typeof(List<Thing>),typeof(TraitCrafter),typeof(bool)})]static class RecipePatch{static void Prefix(Recipe __instance,List<Thing> ings,bool model,out List<Thing>? __state){__state=CraftCore.Prep(__instance,ings,model);}static void Postfix(List<Thing>? __state,Thing __result){if(__result!=null)CraftCore.Give(__state);}}
[HarmonyPatch(typeof(RecipeCard),nameof(RecipeCard.Craft),new Type[]{typeof(BlessedState),typeof(bool),typeof(List<Thing>),typeof(TraitCrafter),typeof(bool)})]static class RecipeCardPatch{static void Prefix(RecipeCard __instance,List<Thing> ings,bool model,out List<Thing>? __state){__state=CraftCore.Prep(__instance,ings,model);}static void Postfix(List<Thing>? __state,Thing __result){if(__result!=null)CraftCore.Give(__state);}}
[HarmonyPatch(typeof(MiniGame),nameof(MiniGame.Deactivate),new Type[]{})]static class CasinoPatch{static void Prefix(MiniGame __instance){if(!Plugin.Casino.Value||__instance?.balance==null||__instance.balance.changeCoin<=0)return;int a=Math.Min(Plugin.CasinoCap.Value,Plugin.Luck()/Math.Max(1,Plugin.CasinoDiv.Value));if(EClass.rnd(100)<a)__instance.balance.changeCoin+=Math.Max(1,__instance.balance.changeCoin/2);}}
