[HarmonyPatch(typeof(AI_Steal),nameof(AI_Steal.Perform),new Type[]{})]static class StealAttemptRollPatch{static void Prefix(){StealAttemptContext.roll=EClass.rnd(10000);StealAttemptContext.has=true;}}
[HarmonyPatch]static class StealWeightNarrowPatch{static readonly MethodInfo Getter=typeof(Card).GetProperty("ChildrenAndSelfWeight",BindingFlags.Instance|BindingFlags.Public|BindingFlags.NonPublic)?.GetGetMethod(true)!;static readonly MethodInfo Helper=typeof(StealWeightNarrowPatch).GetMethod(nameof(EffectiveWeight),BindingFlags.Static|BindingFlags.NonPublic)!;static IEnumerable<MethodBase> TargetMethods(){foreach(var t in Nested(typeof(AI_Steal)))foreach(var m in t.GetMethods(BindingFlags.Instance|BindingFlags.Static|BindingFlags.Public|BindingFlags.NonPublic))if(!m.IsAbstract&&!m.ContainsGenericParameters&&Calls(m))yield return m;}static IEnumerable<Type> Nested(Type r){foreach(var t in r.GetNestedTypes(BindingFlags.Public|BindingFlags.NonPublic)){yield return t;foreach(var c in Nested(t))yield return c;}}static bool Calls(MethodBase m){if(Getter==null)return false;try{var il=m.GetMethodBody()?.GetILAsByteArray();if(il==null)return false;int tok=Getter.MetadataToken;for(int i=0;i+4<il.Length;i++){byte op=il[i];if((op==0x28||op==0x6f)&&BitConverter.ToInt32(il,i+1)==tok)return true;}}catch{}return false;}static long EffectiveWeight(Card target){long w=target==null?0:target.ChildrenAndSelfWeight;if(!Plugin.StealWeight.Value||target==null||EClass.pc==null)return w;long limit=(long)EClass.pc.Evalue(281)*200L+(long)EClass.pc.STR*100L+1000L;if(w<=limit||limit<=0)return w;int b=Math.Min(Plugin.StealWeightCap.Value,Plugin.Luck()/Math.Max(1,Plugin.StealWeightDiv.Value));int chance=(int)Math.Max(1L,Math.Min(b,(long)b*limit/Math.Max(1L,w)));if(!StealAttemptContext.has){StealAttemptContext.roll=EClass.rnd(10000);StealAttemptContext.has=true;}return StealAttemptContext.roll<chance*100?limit:w;}static IEnumerable<CodeInstruction> Transpiler(IEnumerable<CodeInstruction> ins){foreach(var ci in ins){if(Getter!=null&&ci.operand is MethodInfo m&&m==Getter&&(ci.opcode==OpCodes.Call||ci.opcode==OpCodes.Callvirt))yield return new CodeInstruction(OpCodes.Call,Helper);else yield return ci;}}}
[HarmonyPatch(typeof(GrowSystem),nameof(GrowSystem.TryPopSeed),new Type[]{typeof(Chara)})]static class SeedLuckNarrowPatch{static readonly MethodInfo Rnd=typeof(EClass).GetMethod(nameof(EClass.rnd),new Type[]{typeof(int)})!;static readonly MethodInfo Helper=typeof(SeedLuckNarrowPatch).GetMethod(nameof(SeedRnd),BindingFlags.Static|BindingFlags.NonPublic)!;static int SeedRnd(int max,Chara c){if(!Plugin.SeedLuck.Value||c==null||!c.IsPC)return EClass.rnd(max);return EClass.rnd(Plugin.Reduce(max,Plugin.Rel(Plugin.SeedDiv,Plugin.SeedCap)));}static IEnumerable<CodeInstruction> Transpiler(IEnumerable<CodeInstruction> ins){int n=0;foreach(var ci in ins){if(ci.operand is MethodInfo m&&m==Rnd&&(ci.opcode==OpCodes.Call||ci.opcode==OpCodes.Callvirt)&&n++==0){yield return new CodeInstruction(OpCodes.Ldarg_1);yield return new CodeInstruction(OpCodes.Call,Helper);}else yield return ci;}}}
[HarmonyPatch(typeof(Card),nameof(Card.MakeEgg),new Type[]{typeof(bool),typeof(int),typeof(bool),typeof(int),typeof(BlessedState?)})]static class FertEggLuckNarrowPatch{static void Prefix(Card __instance,ref int fertChance){if(!Plugin.FertEggLuck.Value||__instance==null||!__instance.IsPCFaction||fertChance<=1)return;fertChance=Plugin.Reduce(fertChance,Plugin.Rel(Plugin.EggDiv,Plugin.EggCap));}}
[HarmonyPatch]static class ScratchPrizeNarrowPatch{static readonly MethodInfo Rnd=typeof(EClass).GetMethod(nameof(EClass.rnd),new Type[]{typeof(int)})!;static readonly MethodInfo Helper=typeof(ScratchPrizeNarrowPatch).GetMethod(nameof(R),BindingFlags.Static|BindingFlags.NonPublic)!;static IEnumerable<MethodBase> TargetMethods(){foreach(var m in Methods(typeof(TraitCrafter)))if(m.Name.Contains("g__Prize"))yield return m;}static IEnumerable<MethodBase> Methods(Type r){foreach(var m in r.GetMethods(BindingFlags.Static|BindingFlags.Instance|BindingFlags.Public|BindingFlags.NonPublic))yield return m;foreach(var t in r.GetNestedTypes(BindingFlags.Public|BindingFlags.NonPublic))foreach(var m in Methods(t))yield return m;}static int R(int max){return !Plugin.ScratchLuck.Value||max<=1?EClass.rnd(max):EClass.rnd(Plugin.Reduce(max,Plugin.Rel(Plugin.ScratchDiv,Plugin.ScratchCap)));}static IEnumerable<CodeInstruction> Transpiler(IEnumerable<CodeInstruction> ins){foreach(var ci in ins){if(ci.operand is MethodInfo m&&m==Rnd&&(ci.opcode==OpCodes.Call||ci.opcode==OpCodes.Callvirt))yield return new CodeInstruction(OpCodes.Call,Helper);else yield return ci;}}}
[HarmonyPatch]static class TreasureRarityNarrowPatch{static readonly MethodInfo Rnd=typeof(EClass).GetMethod(nameof(EClass.rnd),new Type[]{typeof(int)})!;static readonly MethodInfo Helper=typeof(TreasureRarityNarrowPatch).GetMethod(nameof(R),BindingFlags.Static|BindingFlags.NonPublic)!;static IEnumerable<MethodBase> TargetMethods(){foreach(var m in Methods(typeof(ThingGen)))if(m.Name.Contains("g__SetRarity"))yield return m;}static IEnumerable<MethodBase> Methods(Type r){foreach(var m in r.GetMethods(BindingFlags.Static|BindingFlags.Instance|BindingFlags.Public|BindingFlags.NonPublic))yield return m;foreach(var t in r.GetNestedTypes(BindingFlags.Public|BindingFlags.NonPublic))foreach(var m in Methods(t))yield return m;}static int R(int max){return !Plugin.TreasureLuck.Value||(max!=100&&max!=20)?EClass.rnd(max):EClass.rnd(Plugin.Reduce(max,Plugin.Rel(Plugin.TreasureDiv,Plugin.TreasureCap)));}static IEnumerable<CodeInstruction> Transpiler(IEnumerable<CodeInstruction> ins){foreach(var ci in ins){if(ci.operand is MethodInfo m&&m==Rnd&&(ci.opcode==OpCodes.Call||ci.opcode==OpCodes.Callvirt))yield return new CodeInstruction(OpCodes.Call,Helper);else yield return ci;}}}
